# Repo root discovery
REPO_ROOT = Path(os.environ.get("BIOTECH_REPO", Path(__file__).resolve().parent.parent)).resolve()
DATA_DIR = REPO_ROOT / "data"
SNAPSHOTS_DIR = DATA_DIR / "snapshots"
ARTIFACTS_DIR = REPO_ROOT / "artifacts"
TOOLS_DIR = REPO_ROOT / "tools"

# Output framing
_OUTPUT_FRAMING = "ndjson"
_DATE_PATTERN = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def _validate_date(date_str: str) -> bool:
    """Validate YYYY-MM-DD date format."""
    if not _DATE_PATTERN.match(date_str):
        return False
    try:
        datetime.strptime(date_str, "%Y-%m-%d")
        return True
    except ValueError:
        return False


def _read_message_payloads() -> list[str]:
    """Read JSON-RPC message payloads from stdin."""
    messages = []
    for line in sys.stdin:
        line = line.rstrip("\n\r")
        if line:
            messages.append(line)
    return messages


def _write(obj: Any) -> None:
    """Write JSON-RPC response(s) to stdout."""
    if isinstance(obj, list):
        for item in obj:
            print(json.dumps(item, separators=(",", ":")))
    else:
        print(json.dumps(obj, separators=(",", ":")))


def _success_response(request_id: Any, result: Any) -> dict:
    """Build JSON-RPC 2.0 success response."""
    return {
        "jsonrpc": "2.0",
        "id": request_id,
        "result": result,
    }


def _error_response(request_id: Any, code: int, message: str, data: Any = None) -> dict:
    """Build JSON-RPC 2.0 error response."""
    error: dict[str, Any] = {"code": code, "message": message}
    if data is not None:
        error["data"] = data
    return {
        "jsonrpc": "2.0",
        "id": request_id,
        "error": error,
    }


def list_snapshots() -> dict[str, Any]:
    """List available dated snapshots (YYYY-MM-DD)."""
    if not SNAPSHOTS_DIR.exists():
        return {
            "status": "UNAVAILABLE",
            "reason": f"snapshots dir not found: {SNAPSHOTS_DIR}",
            "snapshots": [],
        }

    snapshots = []
    for d in sorted(SNAPSHOTS_DIR.iterdir()):
        if d.is_dir() and _validate_date(d.name):
            snapshots.append({
                "date": d.name,
                "path": str(d),
                "exists": True,
            })

    return {
        "status": "OK",
        "count": len(snapshots),
        "snapshots": snapshots,
    }


def read_latest_snapshot_manifest(date: str | None = None) -> dict[str, Any]:
    """Read snapshot_manifest.json for a given date (or latest)."""
    if date is None:
        # Find latest snapshot
        if not SNAPSHOTS_DIR.exists():
            return {
                "status": "UNAVAILABLE",
                "reason": "snapshots directory not found",
            }
        dates = [d.name for d in SNAPSHOTS_DIR.iterdir() if d.is_dir() and _validate_date(d.name)]
        if not dates:
            return {"status": "UNAVAILABLE", "reason": "no snapshots found"}
        date = sorted(dates)[-1]
    elif not _validate_date(date):
        return {
            "status": "INVALID_DATE",
            "reason": f"invalid date format: {date}; expected YYYY-MM-DD",
        }

    manifest_path = SNAPSHOTS_DIR / date / "snapshot_manifest.json"
    if not manifest_path.exists():
        return {
            "status": "MISSING",
            "date": date,
            "path": str(manifest_path),
            "reason": "manifest file not found",
        }

    try:
        with open(manifest_path) as f:
            manifest = json.load(f)
        return {
            "status": "OK",
            "date": date,
            "manifest": manifest,
        }
    except (json.JSONDecodeError, OSError) as e:
        return {
            "status": "ERROR",
            "date": date,
            "reason": f"failed to read manifest: {e}",
        }


def read_gate_verdicts(limit: int = 100) -> dict[str, Any]:
    """Read gate_verdict_ledger.jsonl (historical gate verdicts)."""
    ledger_path = ARTIFACTS_DIR / "gate_verdict_ledger.jsonl"
    if not ledger_path.exists():
        return {
            "status": "MISSING",
            "path": str(ledger_path),
            "reason": "gate verdict ledger not found",
            "fallback": "check artifacts/ees_gate_diagnostics.json in snapshots",
        }

    verdicts = []
    try:
        with open(ledger_path) as f:
            for i, line in enumerate(f):
                if i >= limit:
                    break
                line = line.rstrip("\n\r")
                if line:
                    verdicts.append(json.loads(line))
    except (json.JSONDecodeError, OSError) as e:
        return {
            "status": "ERROR",
            "reason": f"failed to read ledger: {e}",
        }

    return {
        "status": "OK",
        "count": len(verdicts),
        "verdicts": verdicts,
        "note": f"returned {min(len(verdicts), limit)} of {len(verdicts)} records",
    }


