def list_disease_map_artifacts(date: str | None = None) -> dict[str, Any]:
    """List disease map artifacts from a scientific cartography run."""
    if date is None:
        # Find latest
        if not ARTIFACTS_DIR.exists():
            return {"status": "UNAVAILABLE", "reason": "artifacts dir not found"}
        sc_dir = ARTIFACTS_DIR / "scientific_cartography"
        if not sc_dir.exists():
            return {
                "status": "UNAVAILABLE",
                "reason": "scientific_cartography dir not found",
            }
        dates = [d.name for d in sc_dir.iterdir() if d.is_dir() and _validate_date(d.name)]
        if not dates:
            return {"status": "UNAVAILABLE", "reason": "no cartography snapshots found"}
        date = sorted(dates)[-1]

    cart_path = ARTIFACTS_DIR / "scientific_cartography" / date
    if not cart_path.exists():
        return {
            "status": "MISSING",
            "date": date,
            "reason": "cartography dir not found",
        }

    artifacts = []
    for item in sorted(cart_path.iterdir()):
        if item.is_file():
            artifacts.append({
                "name": item.name,
                "type": "file",
                "size_bytes": item.stat().st_size,
            })
        elif item.is_dir() and item.name != "__pycache__":
            artifacts.append({
                "name": item.name,
                "type": "directory",
                "items": len(list(item.iterdir())),
            })

    return {
        "status": "OK",
        "date": date,
        "path": str(cart_path),
        "artifact_count": len(artifacts),
        "artifacts": artifacts,
    }


def read_semgrep_findings() -> dict[str, Any]:
    """Read semgrep rules and report on findings availability."""
    rules_path = REPO_ROOT / ".semgrep" / "governance.yml"
    findings_status = "NOT_FOUND"
