    result: dict[str, Any] = {
        "status": "OK",
        "findings_artifact": {
            "status": findings_status,
            "note": findings_note,
            "source": "GitHub Actions (semgrep-governance-audit.yml)",
        },
        "rules": {
            "status": "MISSING",
