        except OSError as e:
            result["rules"]["error"] = str(e)

    return result


def run_readonly_diagnostics_plan(
    snapshot_date: str | None = None,
    ctgov_cache_path: str | None = None,
) -> dict[str, Any]:
    """Plan (don't execute) a readonly diagnostics run."""
    # Validate snapshot if provided
    if snapshot_date and not _validate_date(snapshot_date):
        return {
            "status": "INVALID_DATE",
            "reason": f"invalid snapshot date: {snapshot_date}",
        }

    # Find latest snapshot if not provided
    if snapshot_date is None:
        if not SNAPSHOTS_DIR.exists():
            return {"status": "UNAVAILABLE", "reason": "snapshots dir not found"}
        dates = [d.name for d in SNAPSHOTS_DIR.iterdir() if d.is_dir() and _validate_date(d.name)]
        if not dates:
            return {"status": "UNAVAILABLE", "reason": "no snapshots found"}
        snapshot_date = sorted(dates)[-1]

    snapshot_dir = SNAPSHOTS_DIR / snapshot_date
    if not snapshot_dir.exists():
        return {
            "status": "MISSING",
            "snapshot_date": snapshot_date,
            "reason": "snapshot directory not found",
        }

    # Default ctgov_cache to data/ctgov_cache
    if ctgov_cache_path is None:
        ctgov_cache_path = str(DATA_DIR / "ctgov_cache")
    ctgov_cache_exists = Path(ctgov_cache_path).exists()

    # Diagnostic script
    diag_script = TOOLS_DIR / "run_scientific_cartography_diagnostics.py"
    diag_exists = diag_script.exists()

    return {
        "status": "OK",
        "plan": {
            "snapshot_date": snapshot_date,
            "snapshot_dir": str(snapshot_dir),
            "snapshot_exists": True,
            "ctgov_cache_path": ctgov_cache_path,
            "ctgov_cache_exists": ctgov_cache_exists,
            "script_path": str(diag_script),
            "script_exists": diag_exists,
            "command": (
                f"python {diag_script} "
                f"--as-of-date {snapshot_date} "
                f"--snapshot-dir {snapshot_dir} "
                f"--ctgov-cache {ctgov_cache_path} "
                f"--output-dir /tmp/biotech-mcp-diag-{snapshot_date} "
