def _handle_call_request(tool_name: str, arguments: dict) -> Any:
    """Dispatch a tool call."""
    if tool_name == "list_snapshots":
        return list_snapshots()
    elif tool_name == "read_latest_snapshot_manifest":
        return read_latest_snapshot_manifest(arguments.get("date"))
    elif tool_name == "read_gate_verdicts":
        return read_gate_verdicts(arguments.get("limit", 100))
    elif tool_name == "read_phase2_health":
        return read_phase2_health(arguments.get("date"))
    elif tool_name == "read_rankings_schema":
        return read_rankings_schema(arguments.get("date"))
    elif tool_name == "read_event_ev_feature_coverage":
        return read_event_ev_feature_coverage(arguments.get("date"))
    elif tool_name == "read_forward_eval_ic_ledger":
        return read_forward_eval_ic_ledger()
    elif tool_name == "read_scientific_cartography_status":
        return read_scientific_cartography_status(arguments.get("date"))
    elif tool_name == "list_disease_map_artifacts":
        return list_disease_map_artifacts(arguments.get("date"))
    elif tool_name == "read_semgrep_findings":
        return read_semgrep_findings()
    elif tool_name == "run_readonly_diagnostics_plan":
        return run_readonly_diagnostics_plan(
            arguments.get("snapshot_date"),
            arguments.get("ctgov_cache_path"),
        )
    else:
        return {
            "error": f"unknown tool: {tool_name}",
            "available_tools": [t["name"] for t in _handle_tools_request()["tools"]],
        }


def _handle_message(message: dict) -> dict | None:
    """Handle a single JSON-RPC message."""
    request_id = message.get("id")
    method = message.get("method", "")

    # Handle tools/list
    if method == "tools/list":
        return _success_response(request_id, _handle_tools_request())

    # Handle tools/call
    if method == "tools/call":
        tool_name = message.get("params", {}).get("name")
        arguments = message.get("params", {}).get("arguments", {})
        if not tool_name:
            return _error_response(request_id, -32602, "missing tool name")
        result = _handle_call_request(tool_name, arguments)
        return _success_response(request_id, result)

    # Unknown method
    return _error_response(request_id, -32601, f"unknown method: {method}")


def main() -> int:
    """Main entry point."""
    messages_input = _read_message_payloads()
    responses = []

    for line in messages_input:
        try:
            message = json.loads(line)
        except json.JSONDecodeError as exc:
            responses.append(_error_response(None, -32700, f"parse error: {exc}"))
            continue

        messages = message if isinstance(message, list) else [message]
        for msg in messages:
            resp = _handle_message(msg)
            if resp is not None:
                responses.append(resp)

    if responses:
        _write(responses if isinstance(message, list) else responses[0])

    return 0


if __name__ == "__main__":
    sys.exit(main())
